-/* Decorative code streams stay clear of names and controller hints. */
-static int matrix_cell(unsigned row, unsigned column) {
-    return row == 2 || (row == 20 && (show_checks || column < 40)) ||
-           (!show_checks && column == 38 && row >= 5 && row <= 19);
-}
